import{_ as d,C as s,o as n,c as e,j as t,E as l,a as o,a3 as r}from"./chunks/framework.C6R8kWFE.js";const p=JSON.parse(`{"title":"2-hafta (Mentor)","description":"","frontmatter":{"title":"2-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"10-sinf (BI & ML)","link":"/mentor/10-sinf-bi/"},"n":2,"bob":"I-bob · Ma’lumotlar muhandisligiga kirish va ma’lumotlarni boshqarish","lessons":[{"g":4,"title":"4-dars: Ma’lumot formatlari: Parquet va Columnar saqlash formati (Snappy siqish, CSV vs Parquet)","lead":"Katta hajmdagi ma'lumotlar olamida saqlash joyi va o'qish tezligi hal qiluvchi ahamiyatga ega. Ushbu darsda biz zamonaviy analitika poydevori bo'lgan Apache Parquet formatining ichki mo'jizalarini, ustunli saqlash tamoyilini va Snappy siqish qudratini o'rganamiz.","link":"/mentor/10-sinf-bi/hafta-02/dars-1","slide":"/slaydlar/10-sinf-bi/hafta-02/dars-1.html","test":"/slaydlar/10-sinf-bi/hafta-02/dars-1-test.html"},{"g":5,"title":"5-dars: Ma’lumot formatlari: Avro va formatlarni chuqur taqqoslash","lead":"Real-time rejimida millionlab voqealarni uzatishda har bir bayt hisobda turadi. Ushbu darsda biz Apache Kafka va oqimli tizimlarning sevimlisi bo'lgan Apache Avro formatini hamda Data Engineeringdagi \\"Katta to'rtlik\\" (CSV, JSON, Parquet, Avro) formatlarining o'zaro raqobatini o'rganamiz.","link":"/mentor/10-sinf-bi/hafta-02/dars-2","slide":"/slaydlar/10-sinf-bi/hafta-02/dars-2.html","test":"/slaydlar/10-sinf-bi/hafta-02/dars-2-test.html"},{"g":6,"title":"6-dars: Ma’lumotlar bazalari: konsept va tuzilma. Relatsion ma’lumotlar bazasi (RDBMS) asoslari","lead":"Bugungi raqamli iqtisodiyot — bu milliardlab bog'langan ma'lumotlar oqimidir. Har bir bank o'tkazmasi, har bir xarid va har bir avtorizatsiya ortida ma'lumotlar bazasi va uning qat'iy qoidalari turadi. Ushbu darsda biz nima uchun fayllar davri o'tib, RDBMS (Relatsion ma'lumotlar bazalari) dunyoni boshqarayotganini, Edgar Codd kashfiyotini, ACID tamoyillarini hamda SQL qudratini o'rganamiz.","link":"/mentor/10-sinf-bi/hafta-02/dars-3","slide":"/slaydlar/10-sinf-bi/hafta-02/dars-3.html","test":"/slaydlar/10-sinf-bi/hafta-02/dars-3-test.html"}],"test":"/slaydlar/10-sinf-bi/hafta-02/hafta-test.html"}},"headers":[],"relativePath":"mentor/10-sinf-bi/hafta-02/index.md","filePath":"mentor/10-sinf-bi/hafta-02/index.md"}`),h={name:"mentor/10-sinf-bi/hafta-02/index.md"},m={class:"blk"},u={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},b={class:"blk"},q={id:"baholash-mezoni",tabindex:"-1"};function c(g,a,v,f,y,k){const i=s("Icon");return n(),e("div",null,[t("div",m,[t("h2",u,[l(i,{name:"house"}),a[0]||(a[0]=o(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=t("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=r('<p>Mazkur haftada o&#39;tilgan darslar (Parquet, Avro va RDBMS asoslari) bo&#39;yicha mustaqil bajarish uchun topshiriqlar. Har bir vazifa 20–30 daqiqaga mo&#39;ljallangan.</p><hr><h2 id="_4-dars-ma-lumot-formatlari-parquet-va-columnar-saqlash-formati" tabindex="-1">4-dars: Ma’lumot formatlari: Parquet va Columnar saqlash formati <a class="header-anchor" href="#_4-dars-ma-lumot-formatlari-parquet-va-columnar-saqlash-formati" aria-label="Permalink to &quot;4-dars: Ma’lumot formatlari: Parquet va Columnar saqlash formati&quot;">​</a></h2><ol><li><strong>Format konvertatsiyasi:</strong> O&#39;zingiz qiziqqan soha (futbol statistikasi, ob-havo, e-tijorat yoki maktab baholari) bo&#39;yicha kamida 50 000 qatorlik CSV dataset toping yoki yarating. Uni Python Pandas yordamida Parquet (<code>compression=&#39;snappy&#39;</code>) formatiga o&#39;tkazing.</li><li><strong>Benchmark tahlili:</strong> <code>os.path.getsize()</code> va <code>time</code> moduli yordamida ikkala fayl hajmini hamda bitta ustun bo&#39;yicha o&#39;rtacha qiymat (<code>mean()</code>) hisoblash vaqtini o&#39;lchang.</li><li><strong>Hisobot:</strong> CSV va Parquet natijalarini (hajm, tezlik, tejalgan disk maydoni foizi) taqqoslovchi kichik 1 betlik tahliliy hisobot tayyorlang.</li></ol><hr><h2 id="_5-dars-ma-lumot-formatlari-avro-va-formatlarni-chuqur-taqqoslash" tabindex="-1">5-dars: Ma’lumot formatlari: Avro va formatlarni chuqur taqqoslash <a class="header-anchor" href="#_5-dars-ma-lumot-formatlari-avro-va-formatlarni-chuqur-taqqoslash" aria-label="Permalink to &quot;5-dars: Ma’lumot formatlari: Avro va formatlarni chuqur taqqoslash&quot;">​</a></h2><ol><li><strong>Avro sxemasi loyihalash:</strong> Foydalanuvchi profili uchun <code>user.avsc</code> JSON sxemasini yozing. Unda: <code>user_id</code> (long), <code>username</code> (string), <code>email</code> (string), <code>status</code> (enum: &quot;ACTIVE&quot;, &quot;BANNED&quot;, &quot;PENDING&quot;) va ixtiyoriy <code>telefon</code> (union: [&quot;null&quot;, &quot;string&quot;], default: null) bo&#39;lsin.</li><li><strong>fastavro amaliyoti:</strong> Python <code>fastavro</code> kutubxonasi yordamida kamida 3 nafar namunaviy foydalanuvchini ushbu sxema asosida <code>users.avro</code> fayliga yozing va qayta o&#39;qib konsolga chiqaring.</li><li><strong>Formatlar tanlovi:</strong> 3 xil real ssenariy (Streaming loglar, Data Warehouse analitikasi, Foydalanuvchi mobil sozlamalari) uchun mos formatni (CSV, JSON, Parquet, Avro) tanlang va sababini tushuntiring.</li></ol><hr><h2 id="_6-dars-ma-lumotlar-bazalari-konsept-va-tuzilma-relatsion-ma-lumotlar-bazasi-rdbms-asoslari" tabindex="-1">6-dars: Ma’lumotlar bazalari: konsept va tuzilma. Relatsion ma’lumotlar bazasi (RDBMS) asoslari <a class="header-anchor" href="#_6-dars-ma-lumotlar-bazalari-konsept-va-tuzilma-relatsion-ma-lumotlar-bazasi-rdbms-asoslari" aria-label="Permalink to &quot;6-dars: Ma’lumotlar bazalari: konsept va tuzilma. Relatsion ma’lumotlar bazasi (RDBMS) asoslari&quot;">​</a></h2><ol><li><strong>ERD loyihalash:</strong> O&#39;zingiz bilgan real tizim (kutubxona, avtosalon, poliklinika yoki mehmonxona) uchun kamida 3 ta jadvaldan iborat relyatsion model (ER-diagramma) chizing.</li><li><strong>Kalitlar va cheklovlar:</strong> Modelda qaysi ustunlar Primary Key, qaysilari Foreign Key ekanligini aniq ko&#39;rsating va relyatsion yaxlitlik qoidalarini belgilang.</li><li><strong>Python va SQLite amaliyoti:</strong> Python <code>sqlite3</code> moduli yordamida ushbu 3 ta jadvalni yaratuvchi, har biriga kamida 2 tadan yozuv qo&#39;shuvchi va <code>INNER JOIN</code> orqali birlashgan hisobot chiqaruvchi skript yozing.</li></ol><hr><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><h3 id="baholash-mezonlari-jami-100-ball" tabindex="-1">Baholash mezonlari (Jami 100 ball) <a class="header-anchor" href="#baholash-mezonlari-jami-100-ball" aria-label="Permalink to &quot;Baholash mezonlari (Jami 100 ball)&quot;">​</a></h3><ul><li><strong>4-dars vazifasi (30 ball):</strong> CSV dan Parquet ga muvaffaqiyatli konvertatsiya qilingani, Snappy siqish qo&#39;llangani, hajm va tezlik benchmarki aniq raqamlarda ko&#39;rsatilgani.</li><li><strong>5-dars vazifasi (35 ball):</strong> Valid Avro sxemasi (<code>.avsc</code>) yaratilgani, <code>fastavro</code> orqali binar serializatsiya va deserializatsiyaning xatosiz ishlashi, Big 4 formatlar qiyosiy tahlili to&#39;g&#39;riligi.</li><li><strong>6-dars vazifasi (35 ball):</strong> ERD loyihasi to&#39;g&#39;ri chizilgani (1:N bog&#39;lanishlar), SQLite da PK va FK cheklovlari xatosiz o&#39;rnatilgani, ma&#39;lumotlar to&#39;g&#39;ri kiritilgani va <code>INNER JOIN</code> so&#39;rovi to&#39;g&#39;ri yozilgani.</li></ul><h3 id="eslatma" tabindex="-1">Eslatma <a class="header-anchor" href="#eslatma" aria-label="Permalink to &quot;Eslatma&quot;">​</a></h3><ul><li>O&#39;quvchilarga SQLite&#39;da <code>PRAGMA foreign_keys = ON;</code> qatori ishlatilmasa, Foreign Key cheklovlari tekshirilmay ketishi mumkinligini doimo eslatib turing.</li><li>Avro fayllarni oddiy matn muharririda ochib bo&#39;lmasligi, binar format ekanligi haqida tushuncha bering.</li></ul>',16))]),t("div",b,[t("h2",q,[l(i,{name:"list-checks"}),a[3]||(a[3]=o(" Baholash mezoni ",-1)),a[4]||(a[4]=t("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=r('<p><strong>Mavzular:</strong></p><ol><li>Ma’lumot formatlari: Parquet va Columnar saqlash formati (Snappy siqish, Row Groups, Column Chunks, Projection/Predicate pushdown, CSV vs Parquet)</li><li>Ma’lumot formatlari: Avro va formatlarni chuqur taqqoslash (Binar format, JSON Schema, Schema Evolution, Kafka oqimlari, Big 4 chuqur tahlili)</li><li>Ma’lumotlar bazalari: konsept va tuzilma. Relatsion ma’lumotlar bazasi (RDBMS) asoslari (Fayllar vs DB, Edgar Codd modeli, PK/FK yaxlitligi, ACID tamoyillari, ERD, Python <code>sqlite3</code> va <code>INNER JOIN</code>)</li></ol><hr><h2 id="baholash-mezonlari" tabindex="-1">Baholash mezonlari <a class="header-anchor" href="#baholash-mezonlari" aria-label="Permalink to &quot;Baholash mezonlari&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Tavsif</th><th>Maks. ball</th></tr></thead><tbody><tr><td><strong>Parquet &amp; Columnar tahlil</strong></td><td>Ustunli saqlash mohiyati, Snappy siqish, Pushdown optimizatsiyalarini tushunish va CSV vs Parquet benchmarki</td><td>30 ball</td></tr><tr><td><strong>Avro &amp; Katta taqqoslash</strong></td><td>Avro arxitekturasi, Schema Evolution qoidalari, Kafka streamingdagi o&#39;rni va Big 4 formatlar tahlili</td><td>35 ball</td></tr><tr><td><strong>RDBMS, ACID &amp; SQLite JOIN</strong></td><td>Edgar Codd relyatsion modeli, PK/FK cheklovlari, ACID kafolatlari, ERD chizish va SQLite da JOIN so&#39;rovlari</td><td>35 ball</td></tr><tr><td><strong>JAMI</strong></td><td></td><td><strong>100 ball</strong></td></tr></tbody></table><hr><h2 id="o-quvchilar-natijalari-jadvali" tabindex="-1">O&#39;quvchilar natijalari jadvali <a class="header-anchor" href="#o-quvchilar-natijalari-jadvali" aria-label="Permalink to &quot;O&#39;quvchilar natijalari jadvali&quot;">​</a></h2><table tabindex="0"><thead><tr><th>№</th><th>O&#39;quvchi F.I.Sh.</th><th>Parquet &amp; Benchmark (30)</th><th>Avro &amp; Sxema (35)</th><th>RDBMS, ACID &amp; JOIN (35)</th><th>Jami ball (100)</th><th>Izoh</th></tr></thead><tbody><tr><td>1</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>6</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>7</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>8</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>9</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>10</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>11</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>12</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="mentor-qaydlari-va-tahlil" tabindex="-1">Mentor qaydlari va tahlil <a class="header-anchor" href="#mentor-qaydlari-va-tahlil" aria-label="Permalink to &quot;Mentor qaydlari va tahlil&quot;">​</a></h2><ul><li><strong>Darsdagi asosiy qiyinchiliklar:</strong><ul><li>O&#39;quvchilar ko&#39;pincha CSV va Parquet o&#39;rtasidagi farqni kichik datasetlarda sinab ko&#39;rib, &quot;Parquet nega kattaroq hajm oldi?&quot; degan savol berishadi. Ularga Parquet metadatasining (Footer) o&#39;lchami borligi va ustunli saqlashning haqiqiy kuchi faqat minglab/millionlab qatorlarda namoyon bo&#39;lishini tushuntirish lozim.</li><li>Avro formatida Schema Evolution (moslashuvchanlik) qoidalarida default qiymatsiz yangi maydon qo&#39;shish xatolikka olib kelishini alohida ta&#39;kidlash zarur.</li><li>SQLite&#39;da <code>PRAGMA foreign_keys = ON;</code> qatori yozilmasa, SQLite sukut bo&#39;yicha chet el kalitlarini tekshirmasligini amalda ko&#39;rsatish talab etiladi.</li></ul></li></ul>',11))])])}const P=d(h,[["render",c]]);export{p as __pageData,P as default};
